.gzp-desk{
          bakgrunn:
            radiell gradient (120 % 70 % ved 50 % 0 %, rgba(214,178,110,.05), gjennomsiktig 58 %),
            radiell gradient (130 % 100 % ved 50 % 108 %, rgba(0,0,0,.34), gjennomsiktig 62 %),
            /* trekorn — med stor og uregelmessig avstand (gamle hårlinjer
               Det så ut som fløyel) */
            repeterende-lineær-gradient(92deg,
              rgba(0,0,0,.13) 0 3px,
              gjennomsiktig 3px 17px,
              rgba(255,255,255,.016) 17px 20px,
              gjennomsiktig 20px 41px,
              rgba(0,0,0,.09) 41px 43px,
              gjennomsiktig 43px 74px),
            /* skjøter av brettene */
            repeterende-lineær-gradient(90deg,
              rgba(0,0,0,.42) 0 2px,
              gjennomsiktig 2px 148px),
            lineær gradient(180grader, #33261a 0%, #291e13 52%, #1c150d 100%);
        }
        .gzp-under{
          posisjon: absolutt;
          innfelt: 0;
          bakgrunn: lineær gradient(180grader, #e6d9b6 0%, #d6c599 100%);
          box-shadow: 0 12px 22px rgba(0,0,0,.45), innfelt 0 0 0 1px rgba(120,90,36,.2);
          transform: rotate(-1,15deg) translateY(5px);
        }
        .gzp-under--2{
          bakgrunn: lineær gradient(180deg, #e1d2ab 0%, #cfbd90 100%);
          transform: rotate(.85deg) translateY(9px);
        }
